import json,gzip,re
j=json.load(open('/workspace/assoc_GCST90245847.json'))
assocs=j['_embedded']['associations']
m={}
for a in assocs:
 for loc in a.get('loci',[]):
  for ra in loc.get('strongestRiskAlleles',[]):
   name=ra.get('riskAlleleName','')
   mname=re.match(r'(rs\\d+)',name)
   if mname:
    m[mname.group(1)]=a
print('mapped',len(m))
# compare top significant from our
with gzip.open('inputs/reverse.search.gwas.q2.gz','rt') as f:
 h=f.readline()
 for l in f:
  c=l.rstrip().split('\\t'); r=c[1]
  if r in m:
   a=m[r]
   print(r,'our',c[4],c[5],c[6],c[7],c[8],c[9], 'cat beta',a.get('betaNum'),'se',a.get('standardError'),'p',a.get('pvalueMantissa'),a.get('pvalueExponent'),'allele',ra.get('riskAlleleName'))
PY"

